import{_ as l,a8 as t,o as n,c as s,ah as i,K as o}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const q=JSON.parse('{"title":"文档交付偏好：一致性校验与精炼","description":"","frontmatter":{"type":"preference","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["偏好","文档质量","工作方式"]},"headers":[],"relativePath":"vault/Memory/Preferences/文档交付偏好-一致性与精炼.md","filePath":"vault/Memory/Preferences/文档交付偏好-一致性与精炼.md","lastUpdated":1789374053000}'),_={name:"vault/Memory/Preferences/文档交付偏好-一致性与精炼.md"};function c(u,e,d,p,m,g){const a=t("NolebaseGitContributors"),r=t("NolebaseGitChangelog");return n(),s("div",null,[e[0]||(e[0]=i('<h1 id="文档交付偏好-一致性校验与精炼" tabindex="-1">文档交付偏好：一致性校验与精炼 <a class="header-anchor" href="#文档交付偏好-一致性校验与精炼" aria-label="Permalink to “文档交付偏好：一致性校验与精炼”">​</a></h1><p>用户（帮老适 AI 负责人）在文档工作中反复强调两点（单次会话内至少 3 次主动要求）：</p><ol><li><strong>内部一致性</strong>：新增内容后要求回头检查所有关联位置是否同步（如场景加了、优先级矩阵/数据表/路线图也要加；框架更新后案例库的&quot;待修正&quot;状态也要更新）。</li><li><strong>精炼去冗余</strong>：明确要求&quot;保证内容的精炼和准确性&quot;，主动要求分析并删除重复内容（如 HTML 中跨页重复的量化数据、与表格重复的提示框、未使用的 CSS）。</li></ol><h2 id="如何应用" tabindex="-1">如何应用 <a class="header-anchor" href="#如何应用" aria-label="Permalink to “如何应用”">​</a></h2><ul><li>做增量修改时，<strong>主动做交叉一致性检查</strong>，不等用户提出——列出&quot;哪些位置引用了同一信息&quot;并逐处核对。</li><li>交付前主动做冗余审查（重复词频、跨页重复、未使用样式），报告&quot;精简前后&quot;对比。</li><li>校验结果用具体数字汇报（div 平衡数、词频前后对比、文件大小变化），不要笼统说&quot;已完成&quot;。</li><li>用户同样重视诚实标注：检索案例时标注可信度与&quot;未读全文&quot;，量化数据标注厂商口径——不要硬凑。</li><li>2026-09-12 图文笔记任务中再次验证：改产品名/内容口径时用户明确要求 &quot;不要只改一页，其它页面也要更新&quot;——须全稿 grep 清点所有引用位置 （封面/目录/正文/人群页）逐一同步并<strong>全量重渲</strong>，最后附一致性清点表。</li></ul>',5)),o(a),o(r)])}const b=l(_,[["render",c]]);export{q as __pageData,b as default};
